const CONFIG = [
  { name: '⚡ Action', bg: '#cc3a21', text: '#ffffff', categories: ['Urgent', 'Action', 'Legal', 'Security', 'OTP', 'Auth'] },
  { name: '💼 Work', bg: '#285bac', text: '#ffffff', categories: ['Work', 'Meeting'] },
  { name: '👤 Personal', bg: '#16a766', text: '#ffffff', categories: ['Personal', 'Social', 'Travel'] },
  { name: '💵 Finance', bg: '#fad165', text: '#000000', categories: ['Finance', 'Receipts', 'Shipping'] },
  { name: '🗑️ Ignore', bg: '#666666', text: '#ffffff', categories: ['Newsletters', 'Reading', 'Alerts', 'Promos', 'Spam'] }
];

const staticData = $getWorkflowStaticData('global');
const labelCache = staticData.labelCache || {};

const liveItems = $input.all();
const liveMap = {};
const liveList = [];

for (const item of liveItems) {
  const d = item.json;
  if (d && d.name && d.id) {
    liveMap[d.name] = d.id;
    liveList.push({ id: d.id, name: d.name });
  }
}

const checks = [];
let allOk = true;

for (const cfg of CONFIG) {
  const cachedId = labelCache[cfg.name] || null;
  const liveId = liveMap[cfg.name] || null;
  const ok = Boolean(cachedId && liveId && cachedId === liveId);
  if (!ok) allOk = false;
  checks.push({
    name: cfg.name,
    cachedId,
    liveId,
    ok,
    bg: cfg.bg,
    text: cfg.text
  });
}

return [{
  json: {
    ok: allOk,
    checks,
    live: liveList,
    config: CONFIG
  }
}];

function stripHtml(html) {
  if (!html) return '';
  return html.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();
}

let triggerItems = [];
try {
  triggerItems = $('Gmail Trigger').all();
} catch (e) {
  triggerItems = [];
}

const results = [];

for (const item of triggerItems) {
  const email = item.json || {};
  const labelIds = email.labelIds || [];

  // Skip SENT and DRAFT messages
  if (labelIds.includes('SENT') || labelIds.includes('DRAFT')) {
    continue;
  }

  let fromStr = email.from;
  if (typeof fromStr === 'object' && fromStr !== null) {
    fromStr = fromStr.text || (fromStr.value && fromStr.value[0] && fromStr.value[0].address) || JSON.stringify(fromStr);
  }

  let body = email.textPlain || email.text || '';
  if (!body && (email.textHtml || email.html)) {
    body = stripHtml(email.textHtml || email.html);
  }
  if (!body && email.snippet) {
    body = email.snippet;
  }

  const snippet = (body || '').slice(0, 1500);

  results.push({
    json: {
      messageId: email.id,
      threadId: email.threadId,
      subject: email.subject || '(No Subject)',
      from: fromStr || '',
      snippet
    }
  });
}

return results;

const item = $input.first();
const checks = (item && item.json && item.json.checks) || [];
const problems = [];

for (const c of checks) {
  if (!c.ok) {
    if (c.liveId) {
      problems.push({
        json: {
          problem: 'ID_PROBLEM',
          name: c.name,
          id: c.liveId,
          color: { backgroundColor: c.bg, textColor: c.text }
        }
      });
    } else {
      problems.push({
        json: {
          problem: 'MISSING',
          name: c.name,
          color: { backgroundColor: c.bg, textColor: c.text }
        }
      });
    }
  }
}

return problems;

const staticData = $getWorkflowStaticData('global');
if (!staticData.labelCache) {
  staticData.labelCache = {};
}

const items = $input.all();
for (const item of items) {
  const d = item.json;
  if (d && d.name && d.id) {
    staticData.labelCache[d.name] = d.id;
  }
}

return [{
  json: {
    updated: true,
    labelCache: staticData.labelCache
  }
}];

const staticData = $getWorkflowStaticData('global');
const labelCache = staticData.labelCache || {};

let loopItem = {};
try {
  loopItem = $('Loop').item.json || {};
} catch (e) {
  loopItem = {};
}

const messageId = loopItem.messageId || '';
const threadId = loopItem.threadId || '';
const subject = loopItem.subject || '';

let configList = [];
try {
  configList = $('Check Labels').first().json.config || [];
} catch (e) {
  configList = [];
}

const categoryToLabel = {
  'action': '⚡ Action',
  'work': '💼 Work',
  'personal': '👤 Personal',
  'finance': '💵 Finance',
  'ignore': '🗑️ Ignore'
};

for (const cfg of configList) {
  if (cfg.name) {
    categoryToLabel[cfg.name.toLowerCase()] = cfg.name;
    categoryToLabel[cfg.name.replace(/^[^\w]+/, '').trim().toLowerCase()] = cfg.name;
  }
  if (Array.isArray(cfg.categories)) {
    for (const cat of cfg.categories) {
      categoryToLabel[cat.toLowerCase()] = cfg.name;
    }
  }
}

const currentItem = $json;
let rawContent = '';

if (currentItem.choices && currentItem.choices[0] && currentItem.choices[0].message) {
  rawContent = currentItem.choices[0].message.content || '';
} else if (typeof currentItem === 'string') {
  rawContent = currentItem;
} else if (currentItem.text) {
  rawContent = currentItem.text;
} else if (currentItem.error) {
  rawContent = '';
}

// Strip <think>...</think> block
rawContent = rawContent.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

let extractedCategory = null;
let fallback = false;

// Attempt 1: Extract JSON {"category": "..."}
const jsonMatch = rawContent.match(/\{[\s\S]*?"category"\s*:\s*"([^"]+)"[\s\S]*?\}/i);
if (jsonMatch && jsonMatch[1]) {
  extractedCategory = jsonMatch[1].trim();
} else {
  // Attempt 2: Direct parse of substring
  const bracketMatch = rawContent.match(/\{[\s\S]*\}/);
  if (bracketMatch) {
    try {
      const parsed = JSON.parse(bracketMatch[0]);
      if (parsed.category) {
        extractedCategory = String(parsed.category).trim();
      }
    } catch (e) {}
  }
}

// Attempt 3: Regex fallback for bare category word
if (!extractedCategory) {
  const wordMatch = rawContent.match(/\b(action|work|personal|finance|ignore)\b/i);
  if (wordMatch) {
    extractedCategory = wordMatch[1];
  }
}

let resolvedLabelName = null;
if (extractedCategory) {
  const normalizedCat = extractedCategory.toLowerCase();
  resolvedLabelName = categoryToLabel[normalizedCat] || null;
}

if (!resolvedLabelName) {
  resolvedLabelName = '⚡ Action';
  extractedCategory = extractedCategory || 'Unknown';
  fallback = true;
}

let resolvedLabelId = labelCache[resolvedLabelName] || null;

if (!resolvedLabelId) {
  try {
    const checkItem = $('Check Labels').first().json || {};
    const liveList = checkItem.live || [];
    const found = liveList.find(l => l.name === resolvedLabelName);
    if (found && found.id) {
      resolvedLabelId = found.id;
    }
  } catch (e) {}
}

return {
  messageId,
  threadId,
  subject,
  category: extractedCategory,
  labelName: resolvedLabelName,
  labelId: resolvedLabelId,
  fallback
};

const staticData = $getWorkflowStaticData('global');
delete staticData.labelCache;

const parseItem = $('Parse').first() ? $('Parse').first().json : {};
const err = $json && $json.error ? $json.error.message : 'Label Email failed';

throw new Error(`Label Email failed for messageId ${parseItem.messageId || 'unknown'}: ${err}. Cache cleared.`);
